<script setup>
import { onBeforeUnmount, onMounted, ref, watch } from 'vue'
import cytoscape from 'cytoscape'

const props = defineProps({
  nodes: { type: Array, default: () => [] },
  edges: { type: Array, default: () => [] },
  selectedId: { type: String, default: '' },
  relationType: { type: String, default: '' },
  pathIds: { type: Array, default: () => [] },
})
const emit = defineEmits(['node-select', 'edge-select'])
const container = ref(null)
let cy, observer
const nodeId = (id) => `node:${id}`
const edgeId = (id) => `edge:${id}`
const colour = (type) =>
  ({
    CONCEPT: '#5074cf',
    TASK: '#13a69a',
    ALGORITHM: '#9470d6',
    MODEL: '#d28d38',
    METRIC: '#dc668a',
  })[type] || '#69869d'

function syncElements() {
  if (!cy) return
  const firstLoad = cy.nodes().empty()
  const wanted = new Set([
    ...props.nodes.map((node) => nodeId(node.id)),
    ...props.edges.map((edge) => edgeId(edge.id)),
  ])
  cy.batch(() => {
    cy.elements()
      .filter((element) => !wanted.has(element.id()))
      .remove()
    for (const node of props.nodes) {
      const id = nodeId(node.id),
        current = cy.getElementById(id)
      const data = {
        ...node,
        id,
        originalId: node.id,
        colour: colour(node.type),
      }
      if (current.length) current.data(data)
      else
        cy.add({
          group: 'nodes',
          data,
          position: {
            x: 80 + Math.random() * 280,
            y: 80 + Math.random() * 280,
          },
        })
    }
    for (const edge of props.edges) {
      const id = edgeId(edge.id),
        current = cy.getElementById(id)
      const data = {
        ...edge,
        id,
        originalId: edge.id,
        source: nodeId(edge.source),
        target: nodeId(edge.target),
      }
      if (
        !cy.getElementById(data.source).length ||
        !cy.getElementById(data.target).length
      )
        continue
      if (
        current.length &&
        (current.data('source') !== data.source ||
          current.data('target') !== data.target)
      )
        current.remove()
      const existing = cy.getElementById(id)
      if (existing.length) existing.data(data)
      else cy.add({ group: 'edges', data })
    }
  })
  if (firstLoad && props.nodes.length) layout()
  syncStyles()
}

function syncStyles() {
  if (!cy) return
  cy.batch(() => {
    cy.elements().removeClass('chosen dimmed path filtered')
    cy.edges().forEach((edge) =>
      edge.toggleClass(
        'filtered',
        Boolean(props.relationType && edge.data('type') !== props.relationType),
      ),
    )
    if (props.selectedId) {
      const selected = cy.getElementById(nodeId(props.selectedId))
      if (selected.length) {
        selected.addClass('chosen')
        cy.elements()
          .difference(selected.closedNeighborhood())
          .addClass('dimmed')
      } else cy.getElementById(edgeId(props.selectedId)).addClass('chosen')
    }
    const path = new Set(props.pathIds)
    cy.elements().forEach((element) =>
      element.toggleClass('path', path.has(element.data('originalId'))),
    )
  })
}
function layout() {
  if (!cy) return
  const count = cy.nodes().length
  cy.nodes().forEach((node, index) => {
    const angle = (index / Math.max(count, 1)) * Math.PI * 2
    node.position({
      x: 300 + 240 * Math.cos(angle),
      y: 300 + 240 * Math.sin(angle),
    })
  })
  cy?.layout({
    name: 'cose',
    animate: false,
    padding: 40,
    nodeRepulsion: () => 12000,
    idealEdgeLength: () => 55,
    gravity: 1,
    componentSpacing: 60,
    randomize: false,
  }).run()
}
function fit() {
  cy?.fit(cy.elements(':visible'), 40)
}
function zoomBy(factor) {
  if (cy)
    cy.zoom({
      level: Math.max(0.15, Math.min(3, cy.zoom() * factor)),
      renderedPosition: { x: cy.width() / 2, y: cy.height() / 2 },
    })
}
function focus(id) {
  const node = cy?.getElementById(nodeId(id))
  if (node?.length)
    cy.animate({
      center: { eles: node },
      zoom: Math.max(cy.zoom(), 0.9),
      duration: 180,
    })
}
function focusRelation(id) {
  const edge = cy?.getElementById(edgeId(id))
  if (edge?.length)
    cy.animate({
      center: { eles: edge.connectedNodes() },
      zoom: Math.max(cy.zoom(), 0.9),
      duration: 180,
    })
}
defineExpose({ focus, focusRelation })
onMounted(() => {
  cy = cytoscape({
    container: container.value,
    elements: [],
    minZoom: 0.15,
    maxZoom: 3,
    wheelSensitivity: 0.25,
    style: [
      {
        selector: 'node',
        style: {
          shape: 'ellipse',
          width: 68,
          height: 68,
          'background-color': 'data(colour)',
          label: 'data(name)',
          color: '#263750',
          'font-size': 18,
          'font-family': 'sans-serif',
          'text-valign': 'bottom',
          'text-margin-y': 9,
          'text-wrap': 'wrap',
          'text-max-width': 120,
          'border-width': 4,
          'border-color': '#fff',
        },
      },
      {
        selector: 'edge',
        style: {
          width: 1.7,
          'curve-style': 'bezier',
          'line-color': '#aabbd4',
          'target-arrow-color': '#8d9eb7',
          'target-arrow-shape': 'triangle',
          'arrow-scale': 1.1,
          label: 'data(label)',
          color: '#566985',
          'font-size': 14,
          'text-background-color': '#f6f8fc',
          'text-background-opacity': 0.95,
          'text-background-padding': 4,
          'text-rotation': 'autorotate',
        },
      },
      {
        selector: 'edge[type = "PREREQUISITE_FOR"]',
        style: {
          'line-style': 'dashed',
          'line-color': '#a17cc4',
          'target-arrow-color': '#a17cc4',
        },
      },
      {
        selector: 'node.chosen',
        style: { 'border-color': '#1e3f84', 'border-width': 5 },
      },
      {
        selector: 'edge.chosen',
        style: {
          'line-color': '#3156a4',
          'target-arrow-color': '#3156a4',
          width: 3,
        },
      },
      { selector: '.dimmed', style: { opacity: 0.23 } },
      {
        selector: '.path',
        style: {
          'border-color': '#c07c18',
          'line-color': '#c07c18',
          'target-arrow-color': '#c07c18',
          'border-width': 5,
          opacity: 1,
        },
      },
      { selector: '.filtered', style: { display: 'none' } },
    ],
  })
  cy.on('tap', 'node', (event) =>
    emit('node-select', event.target.data('originalId')),
  )
  cy.on('tap', 'edge', (event) =>
    emit('edge-select', event.target.data('originalId')),
  )
  observer = new ResizeObserver(() => cy?.resize())
  observer.observe(container.value)
  syncElements()
})
watch(() => [props.nodes, props.edges], syncElements, { deep: true })
watch(() => [props.selectedId, props.relationType, props.pathIds], syncStyles, {
  deep: true,
})
onBeforeUnmount(() => {
  observer?.disconnect()
  cy?.destroy()
  cy = null
})
</script>

